using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.Linq;
public static class UpgradeVacuumFlow{public static object Run(){if(EditorApplication.isPlaying)throw new System.Exception("Edit mode required");var p=Object.FindFirstObjectByType<PlayerController>();foreach(var v in p.HeldInstrument.GetComponentsInChildren<VacuumTool>(true)){bool five=v.name=="LVL_5";v.capacityKg=five?150:300;v.suctionKgPerSecond=five?30:60;v.suctionRadius=five?.55f:.8f;v.suctionDepth=five?.35f:.5f;if(v.cylinderInlet==null){v.cylinderInlet=new GameObject("Cylinder grain inlet").transform;v.cylinderInlet.SetParent(v.fillFrame,false);}v.cylinderInlet.localPosition=five?new Vector3(0,0,-.125f):new Vector3(0,.1f,0);v.cylinderInlet.gameObject.layer=v.fillFrame.gameObject.layer;EditorUtility.SetDirty(v);}var settings=Resources.Load<ShovelUpgradeSettings>(ShovelUpgradeSettings.ResourcePath);settings.shovels[4].capacityKg=150;settings.shovels[5].capacityKg=300;EditorUtility.SetDirty(settings);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(p.gameObject.scene);EditorSceneManager.SaveScene(p.gameObject.scene);return true;}}
